set-variable.value:
#[%dw 2.0
output application/json
var rowCount = vars.rowCount
var productCount = sizeOf(vars.sampleProducts)
---
{
    range: 
        if (rowCount == 1)
            "A1:J" ++ productCount
        else
            "A" ++ (rowCount + 2) ++ ":" ++ "J" ++ ((rowCount + 1) + productCount)
}]

ee:variables.ee:set-variable:
%dw 2.0 output application/json
var rowCount = vars.rowCount // number of already existing rows var totalRows = sizeOf(vars.sampleProducts) - 1 // number of new formula sets to generate or new table size .here subtracting -1 is for not to consider the last total row coz they have seperate formulae coz it needs to add all the above rows right?
// only the formula rows, no blanks or SUM var baseFormulas = payload.formulas
// Function to replace only cell references (letter followed by number that's preceded by = or operator) fun incrementRowInFormula(formula: String, newRow: Number) = formula replace /([\=\+\*\-\/\(])([A-Z]+)(\d+)/ with ((matchArray, index) -> matchArray[1] ++ matchArray[2] ++ (newRow as String) )
---
if(rowCount == 1) payload.formulas // if there is no table in data sheet then formulas need not to increment, it can simply add into data sheet from sample sheet else ( (1 to totalRows) map (x) -> baseFormulas[x - 1] default [] map (f) -> incrementRowInFormula(f, rowCount + 1 + x) ) ++ [ ["", "", "", "", "=SUM(J" ++ (rowCount+3)++":J" ++ (rowCount +1 + totalRows) ++ ")"] ]

%dw 2.0
output application/json

var data = vars.incrFormulae
---
(data[0] map ((header, index) ->
    (
        // Create an array of arrays:
        ([header] ++ (data[1 to -1] map (row) -> row[index]))
            // Wrap each value in its own array
            map (item) -> [item]
    )
))

%dw 2.0 output application/json
var formats = vars.sampleFormat
// ✅ Transpose — group all 1st, 2nd, 3rd … values across sets --- (0 to (sizeOf(formats[0]) - 1)) map (i) -> formats map (row) -> [ row[i] ]

%dw 2.0
output application/json

var freepointData = {
    "Products": vars.freepointData.Products
}

var sampleColumn = vars.sampleProducts

// ✅ Fixed normalize function
fun normalize(v) =
    if (v contains "(")
 ((v replace "(" with "-") replace ")" with "")
else v

---
{
  "Date": [["Inventory Date"]] ++ ((2 to (sizeOf(vars.sampleProducts) - 3)) map (() -> [vars.date])) ++ [[""], [""]] ++ [[vars.date]],


  "Products":vars.sampleProducts,

    Quantity: 
        [["Quantity(bbls)"]] ++
        (sampleColumn[1 to (sizeOf(sampleColumn) - 1)] map (p) ->
            [normalize((freepointData.Products[p[0]] default {})["Quantity (bbls)"] default "")]
        ),

    "Unit Price per Gal": vars.unitPriceColumn,

    "Differential per Gal": vars.diffValueColPayload
}

