ee:variables.ee:set-variable:
%dw 2.0
output application/json
---
{
  "Products":
  {
    "Crude": {
      "Quantity (bbls)": round(vars.x.."Crude Received from Pipeline"[0] default 0)
    },
    "Gasoline - Domestic": {
      "Quantity (bbls)": round(vars.y.CBOB[1] default 0)
    },
    "Gasoline - Export": {
      "Quantity (bbls)": round(vars.y."CBOB for Export"[1] default 0)
    },
    "ULSD - Domestic": {
      "Quantity (bbls)": round(vars.y.ULSD[1] default 0)
    },
    "ULSHO - Export": {
      "Quantity (bbls)": round(vars.y."ULSD for Export"[1] default 0)
    },
    "ATB": {
      "Quantity (bbls)": round(vars.y.ATB[1] default 0)
    },
    "JPTS (includes sales to TSAR)": {
      "Quantity (bbls)": round(vars.y."JPTS(includes Sales to TSAR)"[0] default 0)
    },
    "DHT Feed": {
      "Quantity (bbls)": round(vars.x."DHT feed/LSD est. production/(feed to DHT)"[0] default 0)
    },
    "Naphtha": {
      "Quantity (bbls)": round(vars.x."Naphtha production Tnk406"[0] default 0)
    },
    "Isomerate": {
      "Quantity (bbls)": round(vars.x."Isomerate/LSR/Dehex est. production"[0] default 0)
    },
    "Reformate": {
      "Quantity (bbls)": round(vars.x."Heavy/Full Ref. estimated production"[0] default 0)
    }
  }
}
